# ! [unstable (feature = "core_io_borrowed_buf" , issue = "117693")] use split_decls_genesis :: ourprelude :: * ; use crate :: fmt :: { self , Debug , Formatter } ; use crate :: mem :: { self , MaybeUninit } ; use crate :: { cmp , ptr } ; #[doc = " A borrowed byte buffer which is incrementally filled and initialized."] #[doc = ""] #[doc = " This type is a sort of \"double cursor\". It tracks three regions in the buffer: a region at the beginning of the"] #[doc = " buffer that has been logically filled with data, a region that has been initialized at some point but not yet"] #[doc = " logically filled, and a region at the end that is fully uninitialized. The filled region is guaranteed to be a"] #[doc = " subset of the initialized region."] #[doc = ""] #[doc = " In summary, the contents of the buffer can be visualized as:"] #[doc = " ```not_rust"] #[doc = " [             capacity              ]"] #[doc = " [ filled |         unfilled         ]"] #[doc = " [    initialized    | uninitialized ]"] #[doc = " ```"] #[doc = ""] #[doc = " A `BorrowedBuf` is created around some existing data (or capacity for data) via a unique reference"] #[doc = " (`&mut`). The `BorrowedBuf` can be configured (e.g., using `clear` or `set_init`), but cannot be"] #[doc = " directly written. To write into the buffer, use `unfilled` to create a `BorrowedCursor`. The cursor"] #[doc = " has write-only access to the unfilled portion of the buffer (you can think of it as a"] #[doc = " write-only iterator)."] #[doc = ""] #[doc = " The lifetime `'data` is a bound on the lifetime of the underlying data."] pub struct BorrowedBuf < 'data > { #[doc = " The buffer's underlying data."] buf : & 'data mut [MaybeUninit < u8 >] , #[doc = " The length of `self.buf` which is known to be filled."] filled : usize , #[doc = " The length of `self.buf` which is known to be initialized."] init : usize , } impl Debug for BorrowedBuf < '_ > { fn fmt (& self , f : & mut Formatter < '_ >) -> fmt :: Result { f . debug_struct ("BorrowedBuf") . field ("init" , & self . init) . field ("filled" , & self . filled) . field ("capacity" , & self . capacity ()) . finish () } } #[doc = " Creates a new `BorrowedBuf` from a fully initialized slice."] impl < 'data > From < & 'data mut [u8] > for BorrowedBuf < 'data > { #[inline] fn from (slice : & 'data mut [u8]) -> BorrowedBuf < 'data > { let len = slice . len () ; BorrowedBuf { buf : unsafe { (slice as * mut [u8]) . as_uninit_slice_mut () . unwrap () } , filled : 0 , init : len , } } } #[doc = " Creates a new `BorrowedBuf` from an uninitialized buffer."] #[doc = ""] #[doc = " Use `set_init` if part of the buffer is known to be already initialized."] impl < 'data > From < & 'data mut [MaybeUninit < u8 >] > for BorrowedBuf < 'data > { #[inline] fn from (buf : & 'data mut [MaybeUninit < u8 >]) -> BorrowedBuf < 'data > { BorrowedBuf { buf , filled : 0 , init : 0 } } } #[doc = " Creates a new `BorrowedBuf` from a cursor."] #[doc = ""] #[doc = " Use `BorrowedCursor::with_unfilled_buf` instead for a safer alternative."] impl < 'data > From < BorrowedCursor < 'data > > for BorrowedBuf < 'data > { #[inline] fn from (mut buf : BorrowedCursor < 'data >) -> BorrowedBuf < 'data > { let init = buf . init_mut () . len () ; BorrowedBuf { buf : unsafe { buf . buf . buf . get_unchecked_mut (buf . buf . filled ..) } , filled : 0 , init , } } } impl < 'data > BorrowedBuf < 'data > { #[doc = " Returns the total capacity of the buffer."] #[inline] pub fn capacity (& self) -> usize { self . buf . len () } #[doc = " Returns the length of the filled part of the buffer."] #[inline] pub fn len (& self) -> usize { self . filled } #[doc = " Returns the length of the initialized part of the buffer."] #[inline] pub fn init_len (& self) -> usize { self . init } #[doc = " Returns a shared reference to the filled portion of the buffer."] #[inline] pub fn filled (& self) -> & [u8] { unsafe { let buf = self . buf . get_unchecked (.. self . filled) ; buf . assume_init_ref () } } #[doc = " Returns a mutable reference to the filled portion of the buffer."] #[inline] pub fn filled_mut (& mut self) -> & mut [u8] { unsafe { let buf = self . buf . get_unchecked_mut (.. self . filled) ; buf . assume_init_mut () } } #[doc = " Returns a shared reference to the filled portion of the buffer with its original lifetime."] #[inline] pub fn into_filled (self) -> & 'data [u8] { unsafe { let buf = self . buf . get_unchecked (.. self . filled) ; buf . assume_init_ref () } } #[doc = " Returns a mutable reference to the filled portion of the buffer with its original lifetime."] #[inline] pub fn into_filled_mut (self) -> & 'data mut [u8] { unsafe { let buf = self . buf . get_unchecked_mut (.. self . filled) ; buf . assume_init_mut () } } #[doc = " Returns a cursor over the unfilled part of the buffer."] #[inline] pub fn unfilled < 'this > (& 'this mut self) -> BorrowedCursor < 'this > { BorrowedCursor { buf : unsafe { mem :: transmute :: < & 'this mut BorrowedBuf < 'data > , & 'this mut BorrowedBuf < 'this > > (self) } , } } #[doc = " Clears the buffer, resetting the filled region to empty."] #[doc = ""] #[doc = " The number of initialized bytes is not changed, and the contents of the buffer are not modified."] #[inline] pub fn clear (& mut self) -> & mut Self { self . filled = 0 ; self } #[doc = " Asserts that the first `n` bytes of the buffer are initialized."] #[doc = ""] #[doc = " `BorrowedBuf` assumes that bytes are never de-initialized, so this method does nothing when called with fewer"] #[doc = " bytes than are already known to be initialized."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " The caller must ensure that the first `n` unfilled bytes of the buffer have already been initialized."] #[inline] pub unsafe fn set_init (& mut self , n : usize) -> & mut Self { self . init = cmp :: max (self . init , n) ; self } } #[doc = " A writeable view of the unfilled portion of a [`BorrowedBuf`]."] #[doc = ""] #[doc = " The unfilled portion consists of an initialized and an uninitialized part; see [`BorrowedBuf`]"] #[doc = " for details."] #[doc = ""] #[doc = " Data can be written directly to the cursor by using [`append`](BorrowedCursor::append) or"] #[doc = " indirectly by getting a slice of part or all of the cursor and writing into the slice. In the"] #[doc = " indirect case, the caller must call [`advance`](BorrowedCursor::advance) after writing to inform"] #[doc = " the cursor how many bytes have been written."] #[doc = ""] #[doc = " Once data is written to the cursor, it becomes part of the filled portion of the underlying"] #[doc = " `BorrowedBuf` and can no longer be accessed or re-written by the cursor. I.e., the cursor tracks"] #[doc = " the unfilled part of the underlying `BorrowedBuf`."] #[doc = ""] #[doc = " The lifetime `'a` is a bound on the lifetime of the underlying buffer (which means it is a bound"] #[doc = " on the data in that buffer by transitivity)."] #[derive (Debug)] pub struct BorrowedCursor < 'a > { #[doc = " The underlying buffer."] buf : & 'a mut BorrowedBuf < 'a > , } impl < 'a > BorrowedCursor < 'a > { #[doc = " Reborrows this cursor by cloning it with a smaller lifetime."] #[doc = ""] #[doc = " Since a cursor maintains unique access to its underlying buffer, the borrowed cursor is"] #[doc = " not accessible while the new cursor exists."] #[inline] pub fn reborrow < 'this > (& 'this mut self) -> BorrowedCursor < 'this > { BorrowedCursor { buf : unsafe { mem :: transmute :: < & 'this mut BorrowedBuf < 'a > , & 'this mut BorrowedBuf < 'this > > (self . buf ,) } , } } #[doc = " Returns the available space in the cursor."] #[inline] pub fn capacity (& self) -> usize { self . buf . capacity () - self . buf . filled } #[doc = " Returns the number of bytes written to the `BorrowedBuf` this cursor was created from."] #[doc = ""] #[doc = " In particular, the count returned is shared by all reborrows of the cursor."] #[inline] pub fn written (& self) -> usize { self . buf . filled } #[doc = " Returns a mutable reference to the initialized portion of the cursor."] #[inline] pub fn init_mut (& mut self) -> & mut [u8] { unsafe { let buf = self . buf . buf . get_unchecked_mut (self . buf . filled .. self . buf . init) ; buf . assume_init_mut () } } #[doc = " Returns a mutable reference to the whole cursor."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " The caller must not uninitialize any bytes in the initialized portion of the cursor."] #[inline] pub unsafe fn as_mut (& mut self) -> & mut [MaybeUninit < u8 >] { unsafe { self . buf . buf . get_unchecked_mut (self . buf . filled ..) } } #[doc = " Advances the cursor by asserting that `n` bytes have been filled."] #[doc = ""] #[doc = " After advancing, the `n` bytes are no longer accessible via the cursor and can only be"] #[doc = " accessed via the underlying buffer. I.e., the buffer's filled portion grows by `n` elements"] #[doc = " and its unfilled portion (and the capacity of this cursor) shrinks by `n` elements."] #[doc = ""] #[doc = " If less than `n` bytes initialized (by the cursor's point of view), `set_init` should be"] #[doc = " called first."] #[doc = ""] #[doc = " # Panics"] #[doc = ""] #[doc = " Panics if there are less than `n` bytes initialized."] #[inline] pub fn advance (& mut self , n : usize) -> & mut Self { assert ! (n <= self . buf . init - self . buf . filled) ; self . buf . filled += n ; self } #[doc = " Advances the cursor by asserting that `n` bytes have been filled."] #[doc = ""] #[doc = " After advancing, the `n` bytes are no longer accessible via the cursor and can only be"] #[doc = " accessed via the underlying buffer. I.e., the buffer's filled portion grows by `n` elements"] #[doc = " and its unfilled portion (and the capacity of this cursor) shrinks by `n` elements."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " The caller must ensure that the first `n` bytes of the cursor have been properly"] #[doc = " initialised."] #[inline] pub unsafe fn advance_unchecked (& mut self , n : usize) -> & mut Self { self . buf . filled += n ; self . buf . init = cmp :: max (self . buf . init , self . buf . filled) ; self } #[doc = " Initializes all bytes in the cursor."] #[inline] pub fn ensure_init (& mut self) -> & mut Self { let uninit = unsafe { self . buf . buf . get_unchecked_mut (self . buf . init ..) } ; unsafe { ptr :: write_bytes (uninit . as_mut_ptr () , 0 , uninit . len ()) ; } self . buf . init = self . buf . capacity () ; self } #[doc = " Asserts that the first `n` unfilled bytes of the cursor are initialized."] #[doc = ""] #[doc = " `BorrowedBuf` assumes that bytes are never de-initialized, so this method does nothing when"] #[doc = " called with fewer bytes than are already known to be initialized."] #[doc = ""] #[doc = " # Safety"] #[doc = ""] #[doc = " The caller must ensure that the first `n` bytes of the buffer have already been initialized."] #[inline] pub unsafe fn set_init (& mut self , n : usize) -> & mut Self { self . buf . init = cmp :: max (self . buf . init , self . buf . filled + n) ; self } #[doc = " Appends data to the cursor, advancing position within its buffer."] #[doc = ""] #[doc = " # Panics"] #[doc = ""] #[doc = " Panics if `self.capacity()` is less than `buf.len()`."] #[inline] pub fn append (& mut self , buf : & [u8]) { assert ! (self . capacity () >= buf . len ()) ; unsafe { self . as_mut () [.. buf . len ()] . write_copy_of_slice (buf) ; } unsafe { self . set_init (buf . len ()) ; } self . buf . filled += buf . len () ; } #[doc = " Runs the given closure with a `BorrowedBuf` containing the unfilled part"] #[doc = " of the cursor."] #[doc = ""] #[doc = " This enables inspecting what was written to the cursor."] #[doc = ""] #[doc = " # Panics"] #[doc = ""] #[doc = " Panics if the `BorrowedBuf` given to the closure is replaced by another"] #[doc = " one."] pub fn with_unfilled_buf < T > (& mut self , f : impl FnOnce (& mut BorrowedBuf < '_ >) -> T) -> T { let mut buf = BorrowedBuf :: from (self . reborrow ()) ; let prev_ptr = buf . buf as * const _ ; let res = f (& mut buf) ; assert ! (core :: ptr :: addr_eq (prev_ptr , buf . buf)) ; let filled = buf . filled ; let init = buf . init ; self . buf . init = self . buf . filled + init ; self . buf . filled += filled ; res } }